      "html": "<div class=\"api-reference\"><ul>\n<li><a href=\"/ja/projects/capacitor-screenshot-event/docs/api#startwatchevent\"><code>startWatchEvent()</code></a></li>\n<li><a href=\"/ja/projects/capacitor-screenshot-event/docs/api#removewatchevent\"><code>removeWatchEvent()</code></a></li>\n<li><a href=\"/ja/projects/capacitor-screenshot-event/docs/api#addlisteneruserdidtakescreenshot-\"><code>addListener('userDidTakeScreenshot', ...)</code></a></li>\n<li><a href=\"/ja/projects/capacitor-screenshot-event/docs/api#interfaces\">Interfaces</a></li>\n</ul>\n<p></p>\n<span id=\"startwatchevent()\"></span><section class=\"api-entry\"><h4 id=\"startwatchevent\"><code>method</code> startWatchEvent()</h4><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code style=\"color:#e1e4e8\"><span class=\"line\"><span style=\"color:#B392F0\">startWatchEvent</span>() <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#F97583\">&lt;void&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><hr><span id=\"removewatchevent()\"></span></section>\n\n<section class=\"api-entry\"><h4 id=\"removewatchevent\"><code>method</code> removeWatchEvent()</h4><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code style=\"color:#e1e4e8\"><span class=\"line\"><span style=\"color:#B392F0\">removeWatchEvent</span>() <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#F97583\">&lt;void&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><hr><span id=\"addlistener('userdidtakescreenshot'%2C-...)\"></span></section>\n\n<section class=\"api-entry\"><h4 id=\"addlisteneruserdidtakescreenshot-\"><code>method</code> addListener('userDidTakeScreenshot', ...)</h4><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code style=\"color:#e1e4e8\"><span class=\"line\"><span style=\"color:#B392F0\">addListener</span>(eventName: <span style=\"color:#9ECBFF\">'userDidTakeScreenshot'</span>, listenerFunc: () <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#F97583\"> void</span>) <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#F97583\">&lt;</span>PluginListenerHandle<span style=\"color:#F97583\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><table>\n<thead>\n<tr>\n<th>Param</th>\n<th>Type</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>eventName</code></strong></td>\n<td><code>'userDidTakeScreenshot'</code></td>\n</tr>\n<tr>\n<td><strong><code>listenerFunc</code></strong></td>\n<td><code>() =&gt; void</code></td>\n</tr>\n</tbody>\n</table><p><strong>Returns:</strong> <code>Promise&lt;<a href=\"#pluginlistenerhandle\">PluginListenerHandle</a>&gt;</code></p><hr></section>\n\n\n\n<h3 id=\"interfaces\"><a class=\"header-anchor-link\" href=\"#interfaces\" aria-hidden=\"true\"></a> Interfaces</h3>\n<section class=\"api-entry\"><h4 id=\"pluginlistenerhandle\"><code>interface</code> <a class=\"header-anchor-link\" href=\"#pluginlistenerhandle\" aria-hidden=\"true\"></a> PluginListenerHandle</h4><table>\n<thead>\n<tr>\n<th>Prop</th>\n<th>Type</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>remove</code></strong></td>\n<td><code>() =&gt; Promise&lt;void&gt;</code></td>\n</tr>\n</tbody>\n</table></section>\n\n</div>",
